/* Temporary mannequin bank: six instanced draws, shared geometry/materials. */
window.createVillageResidents=function(T,world,api){const R=window.ResidentCombat,group=new T.Group();world.add(group);let owner=null,key='',meshes=[],ids=[];const dummy=new T.Object3D(),color=new T.Color();
 const parts=[{geometry:new T.CylinderGeometry(.25,.3,.85,8),x:0,y:.92},{geometry:new T.SphereGeometry(.23,8,6),x:0,y:1.62},{geometry:new T.CylinderGeometry(.07,.07,.65,6),x:-.36,y:.95,arm:true},{geometry:new T.CylinderGeometry(.07,.07,.65,6),x:.36,y:.95,arm:true},{geometry:new T.CylinderGeometry(.09,.09,.65,6),x:-.14,y:.33},{geometry:new T.CylinderGeometry(.09,.09,.65,6),x:.14,y:.33}];const material=new T.MeshStandardMaterial({color:'#ffffff',roughness:.9});api.material(material);
 function position(v){const p=v.scenePosition;const y=api.navigation.height(p.x,p.z);const stand=(x,z,h)=>api.navigation.canStand?api.navigation.canStand(x,z,h):h>=-.6&&api.navigation.walkable(x,z,h,x+.01,z);if(!stand(p.x,p.z,y)){for(let radius=1;radius<=10;radius++)for(let i=0;i<12;i++){const a=i*Math.PI/6,x=p.x+Math.cos(a)*radius,z=p.z+Math.sin(a)*radius,h=api.navigation.height(x,z);if(stand(x,z,h)){p.x=x;p.z=z;return;}}}}
 function sync(){const g=api.state();R.ensure(g);const next=g.villagers.map(v=>v.id).join('|')+':'+g.phase;if(owner===g&&key===next)return;owner=g;key=next;for(const m of meshes){group.remove(m);m.dispose();}ids=g.villagers.map(v=>v.id);meshes=parts.map(p=>{const m=new T.InstancedMesh(p.geometry,material,ids.length);m.frustumCulled=false;m.castShadow=m.receiveShadow=true;m.userData.residentIds=ids;m.userData.navigationIgnore=m.userData.outlineIgnore=true;group.add(m);return m;});g.villagers.filter(v=>v.alive!==false).forEach(position);update();}
 function update(){const g=api.state(),night=g.phase==='combat';for(let i=0;i<ids.length;i++){const v=g.villagers[i],p=v.scenePosition,y=api.navigation.height(p.x,p.z),enemy=night?g.defense?.enemies.find(e=>e.hp>0&&e.targetResident===v.id):null,angle=enemy?Math.atan2(enemy.x-p.x,enemy.z-p.z):Math.PI*.25;for(let j=0;j<parts.length;j++){const part=parts[j];dummy.position.set(p.x+Math.cos(angle)*part.x,y+part.y,p.z-Math.sin(angle)*part.x);dummy.rotation.set(part.arm&&night?Math.sin((g.defense?.elapsed||0)*5+i)*.45:0,angle,v.combatDown?Math.PI/2:0);dummy.scale.setScalar(v.alive===false?0:1);dummy.updateMatrix();meshes[j].setMatrixAt(i,dummy.matrix);color.set(v.combatDown?'#77726b':v.storyActive?'#b2a07a':'#6e8375');meshes[j].setColorAt(i,color);}}for(const m of meshes){m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true;}}
 const controller={sync,update,roots:()=>meshes,targets(){sync();return R.living(api.state()).filter(v=>!v.combatDown).map(v=>({id:v.id,alive:true,position:{...v.scenePosition,y:api.navigation.height(v.scenePosition.x,v.scenePosition.z)}}));},hit:(id,damage)=>R.hit(api.state(),id,damage)};
 window.villageResidents={targets:g=>g===api.state()?controller.targets():[],hit:(g,id,n)=>g===api.state()?controller.hit(id,n):false};return controller;
};
